import os
import time
import requests
import streamlit as st

# --- Page Configuration ---
st.set_page_config(
    page_title="Market Intelligence Hub", page_icon="📊", layout="wide"
)

st.title("📊 NSE Futures & Strategy Market Intelligence Hub")
st.markdown(
    "Live dashboard displaying automated market reports generated by your GitHub"
    " Actions pipeline."
)

# --- Define Report Files ---
reports = {
    "📈 Confirmed Trends": "confirmed_bullish_bearish_report.txt",
    "⚡ Active Stocks": "active_stocks_report.txt",
    "👁️ Stocks to Watch": "rvol_active_signals_report.txt",
    "🎯 Consolidated Report": "consolidated_strategy_report.txt",
    "📈 Bullish Report": "bullish_report.txt",
    "📉 Bearish Report": "bearish_report.txt",
}


# --- Workflow Trigger Function ---
def trigger_github_workflow():
  try:
    token = st.secrets["GITHUB_TOKEN"].strip()
    owner = "SHANKARNBHAT"
    repo = "Reports-Messenger"
  except Exception:
    st.sidebar.error("⚠️ GITHUB_TOKEN is not configured in Streamlit secrets.")
    return False

  url = f"https://api.github.com/repos/{owner}/{repo}/actions/workflows/pipeline.yml/dispatches"
  headers = {
      "Authorization": f"Bearer {token}",
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
  }

  payload = {"ref": "main"}  # Adjust if your default branch is 'master'

  response = requests.post(url, json=payload, headers=headers)

  if response.status_code == 204:
    return True
  else:
    st.sidebar.error(f"Failed to trigger workflow: {response.text}")
    return False


# --- Direct GitHub Raw Content Loader (Bypasses Container Cache) ---
def load_report_text(filename):
  owner = "SHANKARNBHAT"
  repo = "Reports-Messenger"
  branch = "main"  # Replace with 'master' if your default branch is 'master'

  raw_url = (
      f"https://raw.githubusercontent.com/{owner}/{repo}/{branch}/{filename}"
  )

  try:
    # Adding a timestamp query parameter forces real-time fetching from GitHub
    timestamp = int(time.time())
    response = requests.get(
        raw_url, params={"_cache_bust": timestamp}, timeout=5
    )

    if response.status_code == 200:
      return response.text
  except Exception:
    pass

  # Fallback to local file read if network fetch fails
  if os.path.exists(filename):
    with open(filename, "r", encoding="utf-8") as f:
      return f.read()

  return (
      f"⚠️ Report file '{filename}' not found on GitHub. Click 'Run Workflow"
      " Now' in the sidebar to generate reports."
  )


# --- Sidebar Controls ---
st.sidebar.header("⚙️ Pipeline Controls")
st.sidebar.markdown(
    "If the daily batch hasn't run, you can manually trigger the workflow here:"
)

if st.sidebar.button("🚀 Run Workflow Now"):
  with st.spinner("Triggering GitHub Actions workflow..."):
    success = trigger_github_workflow()
    if success:
      st.sidebar.success(
          "Workflow triggered successfully! Refresh the page in a minute to see"
          " updated reports."
      )

st.sidebar.divider()

# --- Refresh Button ---
if st.sidebar.button("🔄 Refresh Reports"):
  st.rerun()

st.sidebar.markdown("Reports fetch real-time data directly from your repository.")

# --- Create Navigation Tabs ---
tabs = st.tabs(list(reports.keys()))

# --- Render Content in Each Tab ---
for tab, (report_name, filename) in zip(tabs, reports.items()):
  with tab:
    st.subheader(report_name)
    report_content = load_report_text(filename)
    # Using st.code preserves table spacing and column alignments
    st.code(report_content, language="text")
